mapper.select:
SELECT assessment.* FROM hr_employee_skill assessment
JOIN hr_employee employee ON employee.tenant_id = assessment.tenant_id AND employee.id = assessment.employee_id AND employee.deleted = 0
WHERE assessment.tenant_id = #{tenantId}

AND assessment.employee_id = #{query.employeeId}
AND assessment.skill_id = #{query.skillId}
AND assessment.evidence_key = #{evidenceKey}
AND assessment.assessment_status = #{query.status}
ORDER BY assessment.employee_skill_id DESC
